using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class LabLightApply{
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Lighting/"));
 static Material Lamp(){string path=E+"Materials/CL_Lamp.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/S1_Lamp.mat"));m.name="CL_Lamp";AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",new Color(.75f,.82f,.86f));m.SetColor("_EmissionColor",new Color(.78f,.9f,1f)*2.4f);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;m.EnableKeyword("_EMISSION");EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var lamp=Lamp();var modified=new List<object>();foreach(var t in room.Cast<Transform>().Where(t=>t.name.StartsWith("S1_WallTaskLight"))){foreach(var r in t.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>m.name=="S1_Lamp"?lamp:m).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);}var light=t.GetComponentInChildren<Light>();light.transform.localPosition=new Vector3(0,-.16f,.82f);light.transform.localRotation=Quaternion.LookRotation(new Vector3(0,-1,.12f));light.spotAngle=135;light.innerSpotAngle=90;light.intensity=6.5f;light.shadows=LightShadows.Soft;light.shadowBias=.015f;light.shadowNormalBias=.04f;PrefabUtility.RecordPrefabInstancePropertyModifications(light);PrefabUtility.RecordPrefabInstancePropertyModifications(light.transform);modified.Add(new{t.name,light.intensity,light.range});}
 var helpers=room.Find("C01_Perimeter_Lab/Integrated_Worklights").GetComponentsInChildren<Light>();foreach(var l in helpers){l.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(l);}var fill=room.Find("Measurement_Indirect").GetComponent<Light>();fill.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(fill);
 string p=E+"CL_PodCeilingLight.fbx";AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var im=(ModelImporter)AssetImporter.GetAtPath(p);im.importAnimation=false;im.importCameras=false;im.importLights=false;im.isReadable=true;foreach(string name in new[]{"Coat","Dark","Steel","Lamp"})im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"S1_"+name),name=="Lamp"?lamp:AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/S1_"+name+".mat"));im.SaveAndReimport();var old=room.Find("CL_PodCeilingLight");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(p),room);g.name="CL_PodCeilingLight";g.transform.localPosition=new Vector3(0,5.97f,0);foreach(var r in g.GetComponentsInChildren<Renderer>())r.shadowCastingMode=ShadowCastingMode.Off;var pod=room.Find("Pod_Interior_Task").GetComponent<Light>();pod.type=LightType.Spot;pod.transform.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);pod.spotAngle=125;pod.innerSpotAngle=80;pod.shadows=LightShadows.Soft;pod.shadowBias=.015f;pod.shadowNormalBias=.04f;PrefabUtility.RecordPrefabInstancePropertyModifications(pod);PrefabUtility.RecordPrefabInstancePropertyModifications(pod.transform);
 // Scope emission fixes to the two actual connected passages, without editing the shared material.
 var corridor=root.GetComponentsInChildren<Renderer>().Where(r=>(r.transform.parent&&r.transform.parent.name=="B5-T11")||r.name.StartsWith("CD-002_CFD_SealedLight")||r.name.StartsWith("CD-004_CFD_SealedLight")||r.name.StartsWith("CD-006_CFD_SealedLight")||r.name.StartsWith("CD-008_CFD_SealedLight")).Where(r=>r.sharedMaterials.Any(m=>m.name=="CFD_Lamp")).ToArray();foreach(var r in corridor){r.sharedMaterials=r.sharedMaterials.Select(m=>m.name=="CFD_Lamp"?lamp:m).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{wallLights=modified,retiredFloatingSpotlights=helpers.Length,retiredUnattachedFill=1,podFixture=true,corridorDiffusers=corridor.Length,emission=lamp.IsKeywordEnabled("_EMISSION"),giFlags=lamp.globalIlluminationFlags.ToString(),runtimeCodeAdded=false};File.WriteAllText(O+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
